  document.addEventListener('DOMContentLoaded', function() {
    const cards = document.querySelectorAll('.card');
    const columns = document.querySelectorAll('.column');
    const msgElement = document.getElementById('s9-msg');

    // Track the number of cards in each column
    const columnCounts = {
      todo: 0,
      doing: 0,
      done: 0
    };

    // Initialize column counts
    columns.forEach(column => {
      const id = column.id;
      const cardsInColumn = column.querySelectorAll('.card');
      columnCounts[id] = cardsInColumn.length;
    });

    cards.forEach(card => {
      card.addEventListener('dragstart', dragStart);
      card.addEventListener('dragend', dragEnd);
    });

    columns.forEach(column => {
      column.addEventListener('dragover', dragOver);
      column.addEventListener('dragenter', dragEnter);
      column.addEventListener('dragleave', dragLeave);
      column.addEventListener('drop', drop);
    });

    function updateColumnCounts() {
      columns.forEach(column => {
        const id = column.id;
        const cardsInColumn = column.querySelectorAll('.card');
        columnCounts[id] = cardsInColumn.length;
      });
    }

    function dragStart(e) {
      e.dataTransfer.setData('text/plain', e.target.dataset.id);
      e.target.classList.add('dragging');
    }

    function dragEnd(e) {
      e.target.classList.remove('dragging');
    }

    function dragOver(e) {
      e.preventDefault();
    }

    function dragEnter(e) {
      e.preventDefault();
      e.target.classList.add('drag-over');
    }

    function dragLeave(e) {
      e.target.classList.remove('drag-over');
    }

    function drop(e) {
      e.preventDefault();
      e.target.classList.remove('drag-over');

      const id = e.dataTransfer.getData('text/plain');
      const card = document.querySelector(`[data-id="${id}"]`);
      const targetColumn = e.target.closest('.column');

      if (targetColumn && targetColumn.id === 'doing') {
        // Check if doing column already has 3 cards
        if (columnCounts.doing >= 3) {
          msgElement.textContent = 'Doing is full';
          return;
        }
      }

      // Remove the card from its current column
      if (card.parentNode) {
        card.parentNode.removeChild(card);
      }

      // Add the card to the target column
      if (targetColumn) {
        targetColumn.appendChild(card);
        updateColumnCounts();
        msgElement.textContent = ''; // Clear message on successful action
      }
    }
  });
```

