    const addBtn = document.getElementById('s9-add');
    const input = document.getElementById('s9-new');
    const todoList = document.getElementById('s9-todo').querySelector('ul');
    const doingList = document.getElementById('s9-doing').querySelector('ul');
    const doneList = document.getElementById('s9-done').querySelector('ul');
    const todoCount = document.getElementById('s9-count-todo');
    const doingCount = document.getElementById('s9-count-doing');
    const doneCount = document.getElementById('s9-count-done');
    const msgElement = document.getElementById('s9-msg');

    function updateCounts() {
        todoCount.textContent = todoList.children.length;
        doingCount.textContent = doingList.children.length;
        doneCount.textContent = doneList.children.length;
    }

    function addItem() {
        const text = input.value.trim();
        if (text) {
            const li = document.createElement('li');
            li.textContent = text;
            li.dataset.status = 'todo';

            const moveBtn = document.createElement('button');
            moveBtn.textContent = 'Move';
            moveBtn.onclick = function() {
                const currentStatus = li.dataset.status;
                if (currentStatus === 'todo') {
                    // Check if doing column already has 3 items
                    if (doingList.children.length >= 3) {
                        msgElement.textContent = 'Doing is full';
                        return;
                    }
                    li.dataset.status = 'doing';
                    doingList.appendChild(li);
                } else if (currentStatus === 'doing') {
                    li.dataset.status = 'done';
                    doneList.appendChild(li);
                } else {
                    li.dataset.status = 'todo';
                    todoList.appendChild(li);
                }
                updateCounts();
                msgElement.textContent = ''; // Clear message on successful action
            };

            li.appendChild(moveBtn);
            todoList.appendChild(li);
            input.value = '';
            updateCounts();
        }
    }

    addBtn.addEventListener('click', addItem);
    input.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
            addItem();
        }
    });
});
```

